import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { motion, LayoutGroup } from "framer-motion";
import {
  IconChevronLeft,
  IconChevronRight,
  IconChevronsLeft,
  IconChevronsRight,
  IconLoader2,
} from "@tabler/icons-react";
import { cn } from "@/lib/utils";

/* ─── Types ─────────────────────────────────────────────────── */

export type PaginationVariant =
  | "default"
  | "compact"
  | "with-first-last"
  | "load-more";

export type PaginationSize = "sm" | "md";

export interface PaginationProps
  extends Omit<React.HTMLAttributes<HTMLElement>, "onChange"> {
  variant?: PaginationVariant;
  size?: PaginationSize;
  /** Current page (1-indexed). */
  page: number;
  /** Total number of pages. */
  totalPages: number;
  /** Called when the active page changes. */
  onPageChange: (page: number) => void;
  /** Pages shown around the current page (default 1). */
  siblingCount?: number;
  /** Whether a load/fetch operation is in progress (load-more). */
  isLoading?: boolean;
  /** Whether there are more items to load (load-more). */
  hasMore?: boolean;
  /** Callback to load more items (load-more). */
  onLoadMore?: () => void;
  /** Number of items currently loaded (load-more display). */
  loadedCount?: number;
  /** Total number of items (load-more display). */
  totalCount?: number;
}

const indicatorSpring = {
  type: "spring" as const,
  duration: 0.32,
  bounce: 0.12,
};

/* ─── Size maps ─────────────────────────────────────────────── */

const pageButtonSizes: Record<PaginationSize, string> = {
  sm: "size-7 text-xs",
  md: "size-8 text-sm",
};

const navButtonSizes: Record<PaginationSize, string> = {
  sm: "h-7 px-1.5 text-xs [&_svg]:size-3.5",
  md: "h-8 px-2 text-sm [&_svg]:size-4",
};

/* ─── Shared styles ─────────────────────────────────────────── */

const navButtonBase = cn(
  "relative isolate inline-flex shrink-0 items-center justify-center rounded-lg",
  "font-medium leading-none select-none touch-manipulation outline-none",
  "transition-[color,background-color] duration-[150ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
  "text-[var(--muted-foreground)]",
  "hover:text-[var(--foreground)] hover:bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))]",
  "focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
  "disabled:pointer-events-none disabled:opacity-35",
  "[&_svg]:pointer-events-none [&_svg]:shrink-0",
);

const pageButtonBase = cn(
  navButtonBase,
  "rounded-lg tabular-nums",
);

/* ─── Page range calculator ─────────────────────────────────── */

function getPageRange(
  page: number,
  totalPages: number,
  siblingCount: number,
): (number | "ellipsis-start" | "ellipsis-end")[] {
  const totalSlots = siblingCount * 2 + 5; // siblings + first + last + 2 ellipses + current

  if (totalPages <= totalSlots) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const leftSiblingIndex = Math.max(page - siblingCount, 1);
  const rightSiblingIndex = Math.min(page + siblingCount, totalPages);

  const showLeftEllipsis = leftSiblingIndex > 2;
  const showRightEllipsis = rightSiblingIndex < totalPages - 1;

  const items: (number | "ellipsis-start" | "ellipsis-end")[] = [];

  // Always show first page
  items.push(1);

  if (showLeftEllipsis) {
    items.push("ellipsis-start");
  } else {
    // Show pages 2 through leftSiblingIndex - 1
    for (let i = 2; i < leftSiblingIndex; i++) items.push(i);
  }

  // Show siblings + current
  for (let i = leftSiblingIndex; i <= rightSiblingIndex; i++) {
    if (i !== 1 && i !== totalPages) items.push(i);
  }

  if (showRightEllipsis) {
    items.push("ellipsis-end");
  } else {
    for (let i = rightSiblingIndex + 1; i < totalPages; i++) items.push(i);
  }

  // Always show last page
  if (totalPages > 1) items.push(totalPages);

  return items;
}

/* ─── <Pagination> ──────────────────────────────────────────── */

export const Pagination = React.forwardRef<HTMLElement, PaginationProps>(
  (
    {
      variant = "default",
      size = "md",
      page,
      totalPages,
      onPageChange,
      siblingCount = 1,
      isLoading = false,
      hasMore = true,
      onLoadMore,
      loadedCount,
      totalCount,
      className,
      ...props
    },
    ref,
  ) => {
    const layoutId = React.useId();

    /* ── Load More variant ─────────────────── */
    if (variant === "load-more") {
      return (
        <nav
          ref={ref}
          aria-label="Pagination"
          className={cn("flex flex-col items-center gap-3", className)}
          {...props}
        >
          {loadedCount != null && totalCount != null && (
            <p className="text-xs font-medium text-[var(--muted-foreground)] tabular-nums">
              Showing {loadedCount} of {totalCount}
            </p>
          )}
          {hasMore && (
            <button
              type="button"
              disabled={isLoading}
              onClick={() => onLoadMore?.()}
              className={cn(
                "relative h-9 min-w-[140px] overflow-hidden rounded-xl px-4",
                "text-sm font-medium leading-none",
                "border border-[color-mix(in_srgb,var(--foreground)_12%,transparent)]",
                "bg-[var(--background)] text-[var(--foreground)]",
                "transition-[border-color,background-color] duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
                "hover:border-[color-mix(in_srgb,var(--foreground)_20%,transparent)]",
                "hover:bg-[color-mix(in_srgb,var(--foreground)_4%,var(--background))]",
                "focus-visible:ring-2 focus-visible:ring-[color-mix(in_srgb,var(--foreground)_20%,transparent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[var(--background)]",
                "dark:border-white/[0.10] dark:hover:border-white/[0.16]",
                "disabled:opacity-60 disabled:pointer-events-none",
                "outline-none select-none",
              )}
            >

              <span className="relative inline-flex items-center gap-2">
                {isLoading && (
                  <IconLoader2 className="size-3.5 animate-spin" />
                )}
                {isLoading ? "Loading…" : "Load more"}
              </span>
            </button>
          )}
        </nav>
      );
    }

    /* ── Compact variant ───────────────────── */
    if (variant === "compact") {
      return (
        <nav
          ref={ref}
          aria-label="Pagination"
          className={cn("flex items-center gap-2", className)}
          {...props}
        >
          <NavArrow
            direction="prev"
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
            size={size}
          />
          <span className="text-sm font-medium tabular-nums text-[var(--muted-foreground)] select-none px-1">
            <span className="text-[var(--foreground)]">{page}</span>
            <span className="mx-1 opacity-40">/</span>
            {totalPages}
          </span>
          <NavArrow
            direction="next"
            disabled={page >= totalPages}
            onClick={() => onPageChange(page + 1)}
            size={size}
          />
        </nav>
      );
    }

    /* ── Default & With First/Last ─────────── */
    const showFirstLast = variant === "with-first-last";
    const pages = getPageRange(page, totalPages, siblingCount);

    return (
      <nav
        ref={ref}
        aria-label="Pagination"
        className={cn(
          "inline-flex items-center justify-between gap-4 w-full max-w-[360px]",
          "p-1 rounded-xl",
          "bg-[color-mix(in_srgb,var(--foreground)_3%,var(--background))]",
          "border border-[color-mix(in_srgb,var(--foreground)_6%,transparent)]",
          "dark:bg-[#0c0c0e] dark:border-white/[0.04]",
          className
        )}
        {...props}
      >
        <div className="flex items-center gap-1 shrink-0">
          {showFirstLast && (
            <NavArrow
              direction="first"
              disabled={page <= 1}
              onClick={() => onPageChange(1)}
              size={size}
            />
          )}
          <NavArrow
            direction="prev"
            disabled={page <= 1}
            onClick={() => onPageChange(page - 1)}
            size={size}
          />
        </div>

        <LayoutGroup id={layoutId}>
          <div className="flex items-center justify-center gap-0.5 flex-1 min-w-0 mx-1">
            {pages.map((item, i) => {
              if (item === "ellipsis-start" || item === "ellipsis-end") {
                return (
                  <span
                    key={item}
                    className={cn(
                      "inline-flex items-center justify-center text-[var(--muted-foreground)] opacity-50 select-none",
                      pageButtonSizes[size],
                    )}
                  >
                    ⋯
                  </span>
                );
              }
              const isActive = item === page;
              return (
                <button
                  key={item}
                  type="button"
                  aria-label={`Page ${item}`}
                  aria-current={isActive ? "page" : undefined}
                  onClick={() => onPageChange(item)}
                  className={cn(
                    pageButtonBase,
                    pageButtonSizes[size],
                    isActive
                      ? "text-[var(--foreground)]"
                      : "text-[var(--muted-foreground)]",
                  )}
                >
                  {/* Active page indicator */}
                  {isActive && (
                    <motion.span
                      layoutId={`page-active-${layoutId}`}
                      className={cn(
                        "absolute inset-0 rounded-lg",
                        "bg-[color-mix(in_srgb,var(--foreground)_9%,var(--background))]",
                        "border border-[color-mix(in_srgb,var(--foreground)_10%,transparent)]",
                        "dark:bg-[color-mix(in_srgb,var(--foreground)_14%,var(--background))]",
                        "dark:border-white/[0.08]",
                      )}
                      transition={indicatorSpring}
                      style={{ zIndex: -1 }}
                    />
                  )}
                  <span className="relative z-[1]">{item}</span>
                </button>
              );
            })}
          </div>
        </LayoutGroup>

        <div className="flex items-center gap-1 shrink-0">
          <NavArrow
            direction="next"
            disabled={page >= totalPages}
            onClick={() => onPageChange(page + 1)}
            size={size}
          />
          {showFirstLast && (
            <NavArrow
              direction="last"
              disabled={page >= totalPages}
              onClick={() => onPageChange(totalPages)}
              size={size}
            />
          )}
        </div>
      </nav>
    );
  },
);
Pagination.displayName = "Pagination";

/* ─── Nav arrow button ──────────────────────────────────────── */

function NavArrow({
  direction,
  disabled,
  onClick,
  size,
}: {
  direction: "first" | "prev" | "next" | "last";
  disabled: boolean;
  onClick: () => void;
  size: PaginationSize;
}) {
  const labels: Record<string, string> = {
    first: "First page",
    prev: "Previous page",
    next: "Next page",
    last: "Last page",
  };

  const icons: Record<string, React.ReactNode> = {
    first: <IconChevronsLeft />,
    prev: <IconChevronLeft />,
    next: <IconChevronRight />,
    last: <IconChevronsRight />,
  };

  const isForward = direction === "next" || direction === "last";

    return (
      <button
        type="button"
        aria-label={labels[direction]}
        disabled={disabled}
        onClick={onClick}
        className={cn(
          navButtonBase,
          navButtonSizes[size],
          "group/nav",
        )}
      >
        <span
          className={cn(
            "inline-flex transition-transform duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)]",
            !disabled && (isForward ? "group-hover/nav:translate-x-0.5" : "group-hover/nav:-translate-x-0.5")
          )}
        >
          {icons[direction]}
        </span>
      </button>
    );
}
